    internal static OriginalWorldGeometryLateEffectNativeSource LoadWorldGeometryLateEffectNativeSource(string directory, string locale)
    {
        var profile = Profile(locale);
        var exe = File.ReadAllBytes(Path.Combine(directory, $"SAN14CE_{locale}.exe"));
        VerifyHash(exe, profile.ExeHash, "Late effect executable");
        var image = new NativeImage(exe); byte[] code = image.DecodeText(out int codeRva);
        VerifyHash(code, profile.TextHash, "Late effect decoded text");
        var windows = new Dictionary<string,string>(StringComparer.Ordinal);
        foreach (var item in LateEffectWindows(locale))
        { VerifyHash(code.AsSpan(item.Rva-codeRva,item.Length), item.Hash, item.Name); windows.Add(item.Name,item.Hash); }
        bool tc = locale == "TC";
        // Actual source-created ordinary Landscape renderer; its virtual exits
        // establish which shared shader-stage loans are retained before57/58.
        int terrainVtable = tc ? 0x16977D8 : 0x16984D8;
        foreach (var entry in new[] {
            (Offset:0x70, Target:tc?0xBA80F0:0xBA91F0),
            (Offset:0x90, Target:tc?0x97F010:0x9801E0),
            (Offset:0xB0, Target:tc?0x97F040:0x980210),
            (Offset:0xC0, Target:tc?0xBA1A80:0xBA2AC0) })
            if (BinaryPrimitives.ReadUInt64LittleEndian(image.Raw(terrainVtable+entry.Offset,8)) !=
                0x140000000UL + (uint)entry.Target)
                throw new InvalidDataException("Ordinary Terrain renderer virtual stage lifecycle changed.");
        float Read(int tcRva, int scRva, string hash)
        { var bytes = image.Raw(tc ? tcRva : scRva,4); VerifyHash(bytes,hash,"Late effect source scalar"); return BinaryPrimitives.ReadSingleLittleEndian(bytes); }
        float epsilon = Read(0x1343B54,0x1344B54,"9D66C3272BC1792E9FAEFA89F385F9572DAF28B53B0BF5780D4B442309A5588A");
        float bias = Read(0x1343B70,0x1344B70,"FB360F7241A770DC32CADE9A1D1273C92B13BD4959B1C130931312B7FE95E63F");
        return new(locale,profile.ExeHash,profile.TextHash,new ReadOnlyDictionary<string,string>(windows),epsilon,bias);
    }
